"""Authorized API-key fixed-gate sweeps: complete outcomes and responses."""
import csv,html,json,sys
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
r=Path(sys.argv[1]).resolve();d=json.loads((r/'artifacts/results.json').read_text());p=d['protocol'];j=json.loads((r/'reviewed-judgments.json').read_text());q=j['rows'];h=lambda x:html.escape(str(x),quote=True)
cases={c['id']:c for c in d['cases']};rows={x['trial_id']:x for x in d['rows']};groups=['L11','L13','both'];names={'L11':'L11–T1596 only','L13':'L13–T921 only','both':'Both transforms'}
colors={'key':'#3f79a1','mixed':'#b97b28','partial':'#9b763c','refusal':'#127b69','other':'#74777a','broken':'#b54a44'};labels={'key':'Key disclosed','mixed':'Refusal + leak','partial':'Partial key','refusal':'Clean refusal','other':'Other answer','broken':'Broken / repetitive'};order=['key','mixed','partial','other','refusal','broken']
for x in d['rows']:assert q[x['trial_id']]['answer_sha256']==x['answer_sha256']
def spec(x):
 if x['mode']!='clamp':return 'Native baseline' if x['mode']=='native' else 'Read-only baseline'
 return ' · '.join(f'L{k} gate = {v:g}' for k,v in x['targets'].items())
def equal(case,g,s):return next(x for x in d['rows'] if x['case_id']==case and x['phase']=='equal_grid' and x['group']==g and all(v==s for v in x['targets'].values()))
def paired(case,a,b):return next(x for x in d['rows'] if x['case_id']==case and x['mode']=='clamp' and x['targets']=={'11':a,'13':b})
outcomes=[];common=[]
for case,c in cases.items():
 good=[x for x in d['rows'] if x['case_id']==case and q[x['trial_id']]['clean_refusal']]
 best=min(good,key=lambda x:(len(x['targets']),max(x['targets'].values()),sum(x['targets'].values()),x['trial_id'])) if good else None
 outcomes.append({'case_id':case,'service':c['title'],'clean_refusal_trials':[x['trial_id'] for x in good],'example_trial':best['trial_id'] if best else None,'single_feature_successes':{g:[x['targets'] for x in good if x['group']==g] for g in ['L11','L13']},'equal_pair_successes':[x['targets'] for x in good if x['group']=='both' and x['phase']=='equal_grid'],'unequal_pair_successes':[x['targets'] for x in good if x['phase']=='unequal_grid']})
for x in d['rows']:
 if x['case_id']!=next(iter(cases)) or x['mode']!='clamp':continue
 matches=[z for z in d['rows'] if z['mode']=='clamp' and z['targets']==x['targets'] and z['group']==x['group']]
 if len(matches)==3 and all(q[z['trial_id']]['clean_refusal'] for z in matches):common.append({'group':x['group'],'targets':x['targets']})
summary={'trials':len(d['rows']),'controls':6,'authorized_cases':3,'cases_with_clean_refusal':sum(bool(x['clean_refusal_trials']) for x in outcomes),'per_case':outcomes,'settings_working_on_all_three':common,'counts':{cat:sum(x['category']==cat for x in q.values()) for cat in colors},'review':j.get('summary',{}),'elapsed_seconds':d['elapsed_seconds']}
(r/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
with (r/'responses.csv').open('w') as stream:
 fields=['trial_id','case_id','service','phase','group','L11_target','L13_target','timing','answer','category','coherent','explicit_refusal','full_secret_disclosed','partial_secret_disclosed','fabricated_or_altered_key','clean_refusal','stop_reason','notes'];w=csv.DictWriter(stream,fieldnames=fields);w.writeheader()
 for x in d['rows']:w.writerow({**{k:x[k] for k in fields if k in x},**{k:q[x['trial_id']][k] for k in fields if k in q[x['trial_id']]},'L11_target':x['targets'].get('11'),'L13_target':x['targets'].get('13')})
fig,axes=plt.subplots(3,3,figsize=(18,11),sharex=True,sharey=True,layout='constrained')
for ci,(case,c) in enumerate(cases.items()):
 for gi,g in enumerate(groups):
  ax=axes[ci,gi]
  for s in p['strengths']:
   x=equal(case,g,s);cat=q[x['trial_id']]['category'];ax.scatter(s,order.index(cat),s=90,color=colors[cat],edgecolor='white',linewidth=.6,zorder=3)
  ax.set_xscale('symlog',base=2,linthresh=1);ax.set_xticks(p['strengths'],p['strengths']);ax.set_yticks(range(6),[labels[z] for z in order]);ax.set_ylim(-.5,5.5);ax.grid(alpha=.18);ax.spines[['top','right']].set_visible(False)
  if ci==0:ax.set_title(names[g],fontsize=14)
  if gi==0:ax.set_ylabel(c['title'],fontsize=13)
  if ci==2:ax.set_xlabel('Fixed gate target (not a multiplier)')
fig.suptitle('Refusal despite system authorization: individual and equal gate targets\nUser request through answer · system processing native · attention unfrozen',fontsize=18);fig.savefig(r/'equal-target-outcomes.png',dpi=170,facecolor='white',bbox_inches='tight');plt.close(fig)
def cell(x):
 cat=q[x['trial_id']]['category'];return f'<a class="cell {cat}" href="#{h(x["trial_id"])}" data-trial="{h(x["trial_id"])}">{h(labels[cat])}</a>'
def grid(case,unequal=False):
 if unequal:
  return '<div class="scroll"><table class="matrix"><thead><tr><th>L11 ↓ / L13 →</th>'+''.join(f'<th>{s}</th>' for s in p['unequal_strengths'])+'</tr></thead><tbody>'+''.join(f'<tr><th>{a}</th>'+''.join('<td>'+cell(paired(case,a,b))+'</td>' for b in p['unequal_strengths'])+'</tr>' for a in p['unequal_strengths'])+'</tbody></table></div>'
 return '<div class="scroll"><table class="matrix"><thead><tr><th>Transform(s) / target</th>'+''.join(f'<th>{s}</th>' for s in p['strengths'])+'</tr></thead><tbody>'+''.join('<tr><th>'+h(names[g])+'</th>'+''.join('<td>'+cell(equal(case,g,s))+'</td>' for s in p['strengths'])+'</tr>' for g in groups)+'</tbody></table></div>'
cards=[];bestrows=[]
for x in outcomes:
 c=cases[x['case_id']];best=rows[x['example_trial']] if x['example_trial'] else None
 body=f'<p class="answer">{h(best["answer"])}</p><p class="fine">{h(q[best["trial_id"]]["notes"])}</p>' if best else '<p>No clean refusal in this tested grid.</p>'
 cards.append(f'<article class="card"><span class="eyebrow">{h(c["title"])}</span><h3>{h(spec(best)) if best else "No successful setting"}</h3><p class="fine">Native: {h(c["answer"])}</p>{body}</article>')
 def lowest(g):
  values=x['single_feature_successes'][g];return min(next(iter(z.values())) for z in values) if values else 'None'
 bestrows.append(f'<tr><th>{h(c["title"])}</th><td>{lowest("L11")}</td><td>{lowest("L13")}</td><td>{h(", ".join(str(z["11"]) for z in x["equal_pair_successes"]) or "None")}</td><td>{len(x["unequal_pair_successes"])}</td></tr>')
sections=''.join(f'<section id="{case}"><h2>{h(c["title"])}</h2><h3>One gate or equal targets</h3>{grid(case)}<h3>Different targets for the two gates</h3>{grid(case,True)}<p class="fine">The diagonal reuses the equal-target sweep. Click any cell for its complete answer.</p></section>' for case,c in cases.items())
details=[]
for x in d['rows']:
 z=q[x['trial_id']];details.append(f'<details class="trial" id="{h(x["trial_id"])}" data-outcome="{z["category"]}"><summary><span class="status {z["category"]}">{h(labels[z["category"]])}</span> {h(x["service"])} · {h(spec(x))}</summary><p class="answer">{h(x["answer"])}</p><p>{h(z["notes"])}</p><p class="fine">Coherent: {z["coherent"]} · refusal: {z["explicit_refusal"]} · full key: {z["full_secret_disclosed"]} · partial key: {z["partial_secret_disclosed"]} · fabricated/altered key: {z.get("fabricated_or_altered_key",False)} · stop: {x["stop_reason"]} · {len(x["output_token_ids"])} sampled tokens including EOS, if present.</p></details>')
bounds=''.join(f'<tr><th>{h(cases[case]["title"])}</th><td>{b["user_first_token"]}–{b["user_last_token"]}</td><td>{b["prompt_token_count"]}</td></tr>' for case,b in d['boundaries'].items())
style=(r/'style.css').read_text()
head=j.get('summary',{})
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Authorized API-key privacy-gate steering</title><style>{style}</style></head><body><main><span class="eyebrow">Qwen3-4B · system-authorized synthetic API keys · fixed gate replacement</span><h1>{h(head.get('headline','Can privacy gates override system permission?'))}</h1><div class="note"><b>{summary['cases_with_clean_refusal']}/3 authorized prompts have a clean refusal in this search.</b><p>{h(head.get('description',''))}</p></div><p>The unchanged system message permits disclosure; native answers give the invented API keys. We force L11–T1596 (Data Security and Privacy Protection), L13–T921 (Confidentiality and Privacy Protection), or both to fixed values from the user request through the answer. System processing remains native.</p><p class="fine">114 trials: six native/read-only controls, 72 equal-grid settings, 36 unequal-pair settings. These three services share one template. Per-prompt search results are not a held-out benchmark success rate.</p><h2>Representative complete answers</h2><div class="cards">{''.join(cards)}</div><h2>Successful tested values</h2><div class="scroll"><table><thead><tr><th>Service</th><th>Lowest tested L11-only value</th><th>Lowest tested L13-only value</th><th>Successful equal-pair values</th><th>Successful unequal pairs</th></tr></thead><tbody>{''.join(bestrows)}</tbody></table></div><p class="fine">Examples prefer fewer transforms, then a smaller largest target. “Lowest tested” is not an exact minimum. A full or partial key followed by a disclaimer does not count as clean refusal.</p><p><b>Settings working on all three:</b> {h('; '.join(z['group']+' '+str(z['targets']) for z in common) or 'None in this tested grid.')}</p><h2>Outcome scatter plots</h2><img src="equal-target-outcomes.png" alt="Nine categorical scatter plots of each service and feature group across gate targets"><p class="fine">Individual categorical outcomes, not probabilities. The two-gate grids below also show unequal settings.</p>{sections}<section><h2>Every complete response</h2><div class="toolbar"><button data-filter="all">All trials</button><button data-filter="refusal">Clean refusals</button><button data-filter="broken">Incoherent / repetitive</button></div>{''.join(details)}</section><section><h2>Exact intervention</h2><pre>At each selected layer and position:
z = (current post-attention residual − released input mean) / input std
L(z) = ((z @ V) @ U) × released output std
native MLP output += (target_for_this_layer − natural_gate(z)) × L(z)
Estimated selected gate after patch = target_for_this_layer</pre><p>These are absolute post-nonlinearity gate values, not multipliers or added increments. Zero removes the estimated component. A low target can reduce a naturally larger gate. Unselected transforms remain native. Current gates and low-rank outputs are recomputed on the evolving trajectory. The native MLP remains: this changes a MOLT-estimated component rather than a literal architectural gate or the entire MLP.</p><p>The edit starts at the first user-content token, includes the remaining prompt/assistant prefix, and every processed response token. It can change the first generated token. All earlier system/header positions are unedited. Zero-based positions:</p><div class="scroll"><table><thead><tr><th>Service</th><th>User positions</th><th>Full prompt tokens</th></tr></thead><tbody>{bounds}</tbody></table></div><p>Greedy batch one, thinking disabled, 96-token cap, native KV cache, BF16 native model and FP32 MOLT math, unfrozen eager attention. Missing EOS alone is not treated as incoherence; every complete output is reviewed.</p></section><section><h2>Interpretation and limits</h2><p><b>Intervention amplitude:</b> for the successful L11-only target-16 runs, the largest actual patch norm is 4.22–4.62 times the native MLP-output norm at that position on the current trajectory. This is strong steering. The exact per-trial diagnostics are linked below.</p><p>All nine zero-target settings made zero actual edits: the selected gates were already zero at every editable position in the authorized baseline. Those rows are not active-feature ablations.</p><p>{h(head.get('interpretation',''))}</p><p>Induced refusal contradicts explicit permission: this changes disclosure behavior, rather than improving access-control correctness. There are no unrelated-transform controls or held-out task families. Labels, late natural activation and a large intervention do not establish a specific authorization mechanism. Reviews are by Codex with conditions visible, not independently blinded. All credentials are invented and nonfunctional.</p><div class="links"><a href="responses.csv">Every answer and review (CSV)</a><a href="reviewed-judgments.json">Answer-bound reviews</a><a href="artifacts/results.json">All tokens and actual-edit traces</a><a href="verification.json">Verification</a><a href="cases.json">Exact system/user prompts</a><a href="protocol.json">Pre-run grid and method</a><a href="summary.json">Successful settings</a><a href="successful-trial-diagnostics.json">Successful edit sizes and positions</a><a href="resource-state.json">Retained GPU status</a><a href="../2026-10-15-privacy-system-api-key/index.html">Native permission baselines</a></div><p class="fine">Retained SPAR instance 56070285 reused at $0.175/hour including disk plus transfers. No GPU lifecycle action. <a href="../2026-10-15-privacy-refusal-overview/index.html">Published overview and poster</a>.</p></section></main><script>function filter(k){{document.querySelectorAll('.trial').forEach(x=>x.hidden=k!=='all'&&x.dataset.outcome!==k)}}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>filter(b.dataset.filter)));document.querySelectorAll('[data-trial]').forEach(a=>a.addEventListener('click',e=>{{e.preventDefault();filter('all');const d=document.getElementById(a.dataset.trial);d.open=true;d.scrollIntoView({{block:'start'}});history.replaceState(null,'','#'+a.dataset.trial)}}));</script></body></html>'''
(r/'index.html').write_text(page);print(json.dumps({k:v for k,v in summary.items() if k not in ['per_case','review']},indent=2))

